public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    /**
     * Parses the JSON payload and returns an Order object.
     * 
     * @param body The JSON string to parse.
     * @return A populated Order object.
     * @throws PayloadException if validation rules are violated.
     */
    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException();
        }

        Order order = new Order();

        try {
            Object untyped = JSON.deserializeUntyped(body);

            if (!(untyped instanceof Map<String, Object>)) {
                throw new PayloadException();
            }

            Map<String, Object> root = (Map<String, Object>) untyped;

            // Validate Order Number
            String numberStr = (String) root.get('number');
            if (String.isBlank(numberStr)) {
                throw new PayloadException();
            }
            order.orderNumber = numberStr;

            // Parse Date
            Object dateObj = root.get('date');
            if (dateObj != null && String.isNotBlank(String.valueOf(dateObj))) {
                try {
                    order.orderDate = Date.valueOf(String.valueOf(dateObj));
                } catch (Exception e) {
                    // If date is malformed, we continue as per rules which don't specify error for date format
                }
            }

            // Parse Currency
            order.currencyCode = (String) root.get('currency');

            // Parse Customer
            Object customerObj = root.get('customer');
            if (customerObj instanceof Map<String, Object>) {
                Map<String, Object> custMap = (Map<String, Object>) customerObj;
                order.customerEmail = (String) custMap.get('email');
            }

            // Parse Lines
            Object linesObj = root.get('lines');
            if (linesObj instanceof List<Object>) {
                List<Object> linesList = (List<Object>) linesObj;
                for (Object lObj : linesList) {
                    if (!(lObj instanceof Map<String, Object>)) {
                        throw new PayloadException();
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) lObj;

                    // Validate SKU
                    String sku = (String) lineMap.get('sku');
                    if (sku == null) {
                        throw new PayloadException();
                    }

                    // Validate Quantity (non-positive or missing)
                    Object qtyObj = lineMap.get('quantity');
                    if (qtyObj == null) {
                        throw new PayloadException();
                    }
                    Decimal qtyDec = Decimal.valueOf(String.valueOf(qtyObj));
                    if (qtyDec.intValue() <= 0) {
                        throw new PayloadException();
                    }
                    Integer qty = qtyDec.intValue();

                    // Validate UnitPrice (negative or missing)
                    Object uPriceObj = lineMap.get('unitPrice');
                    if (uPriceObj == null) {
                        throw new PayloadException();
                    }
                    Decimal uPrice = Decimal.valueOf(String.valueOf(uPriceObj));
                    if (uPrice < 0) {
                        throw new PayloadException();
                    }

                    // Parse Discount (missing or null means 0)
                    Object discObj = lineMap.get('discount');
                    Decimal discount = (discObj == null) ? 0 : Decimal.valueOf(String.valueOf(discObj));

                    // Calculate Line Total: qty * uPrice * (1 - discount)
                    // Rounded to 2 decimal places with ties rounded half up
                    Decimal lineTotalRaw = qtyDec * uPrice * (1 - discount);
                    Decimal lineTotal = lineTotalRaw.setScale(2, RoundingMode.HALF_UP);

                    Line line = new Line();
                    line.sku = sku;
                    line.quantity = qty;
                    line.unitPrice = uPrice;
                    line.discount = discount;
                    line.lineTotal = lineTotal;

                    order.lines.add(line);
                    order.total += lineTotal;
                }
            }

        } catch (Exception e) {
            // Re-throw if it is already our custom exception, otherwise wrap it
            if (e instanceof PayloadException) {
                throw e;
            }
            throw new PayloadException();
        }

        return order;
    }

    /**
     * Generates an acknowledgement JSON string for the order.
     * 
     * @param order The order to acknowledge.
     * @return A JSON string containing number, status, lineCount, and total.
     */
    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => order.lines.size(),
            'total' => order.total
        };

        return JSON.serialize(ack);
    }
}
