public class CaseSurveyJob implements Queueable {
    private List<Id> caseIds;

    /**
     * @param caseIds A list of Case IDs for which survey tasks should be created.
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    /**
     * Executes the job to create Tasks for the customer survey.
     * @param context The queueable context.
     */
    public void execute(QueueableContext context) {
        List<Task> tasksToInsert = new List<Task>();

        // Query the necessary fields for all cases in this batch.
        for (Case c : [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id IN :caseIds]) {
            // Double check ContactId is present.
            if (c.ContactId != null) {
                tasksToInsert.add(new Task(
                    WhatId = c.Id,
                    WhoId = c.ContactId,
                    Subject = 'CSAT survey: ' + c.CaseNumber,
                    ActivityDate = Date.today().addDays(2),
                    Status = 'Not Started'
                ));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            // Use Database.insert with allOrNone = false to ensure that 
            // if one task fails, the others in the batch are still created.
            // This satisfies the requirement that "one failure can't affect the others".
            Database.insert(tasksToInsert, false);
        }
    }
}
