/**
 * RenewalReminderService
 * 
 * CRITIQUE OF THE PREVIOUS APPROACH:
 * The instruction to call Messaging.sendEmail inside a loop is a bad idea because:
 * 1. Governor Limits: Salesforce limits `sendEmail` to 10 calls per transaction. 
 *    A list of 200 opportunities would cause a LimitException at the 11th record.
 * 2. Uncatchable Exception: A LimitException cannot be caught via try-catch, 
 *    meaning the requirement to "continue if one fails" would fail for the whole batch.
 * 3. Correct Strategy: The proper way to handle individual successes/failures in 
 *    a bulk transaction is to call Messaging.sendEmail once with a list of messages 
 *    and then iterate through the List<Messaging.SendEmailResult> to check 
 *    the `isSuccess()` status of each individual email.
 */
public class RenewalReminderService {

    /**
     * Sends renewal reminders to the owners of the specified opportunities.
     * 
     * @param opportunityIds List of Opportunity IDs to process.
     * @return Integer The number of emails that were successfully sent.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query the necessary fields.
        List<Opportunity> opportunities = [
            SELECT Name, CloseDate, OwnerId 
            FROM Opportunity 
            WHERE Id IN :opportunityIds
        ];

        if (opportunities.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> emailsToSend = new List<Messaging.SingleEmailMessage>();

        // Prepare all email messages in a single loop.
        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();

            // Set the recipient as the opportunity owner.
            email.setTargetObjectId(opp.OwnerId);

            // Prevent the email from being saved as an activity on the record.
            email.setSaveAsActivity(false);

            // Set the subject as required.
            email.setSubject('Renewal due: ' + opp.Name);

            // Set the plain-text body mentioning the close date.
            email.setPlainTextBody('The renewal for ' + opp.Name + ' is due on ' + opp.CloseDate);

            emailsToSend.add(email);
        }

        Integer sentCount = 0;

        try {
            // Call Messaging.sendEmail once (Bulkified).
            // This respects the governor limit and handles all messages in the list.
            List<Messaging.SendEmailResult> results = Messaging.sendEmail(emailsToSend);

            // Iterate through the results to count how many were actually successful.
            // This satisfies the requirement to track success even if individual emails fail.
            for (Messaging.SendEmailResult result : results) {
                if (result.isSuccess()) {
                    sentCount++;
                }
            }
        } catch (Exception e) {
            // If the entire sendEmail call fails (e.g. due to a platform error), 
            // we catch it here to prevent the transaction from crashing.
            System.debug('Error sending bulk emails: ' + e.getMessage());
        }

        return sentCount;
    }
}
