import { LightningElement, wire } from 'lwc';
import { subscribe, unsubscribe, MessageContext, APPLICATION_SCOPE, publish } from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    selectedAccountId = null;
    subscription = null;
    messageContext;

    /**
     * Wired function to handle the MessageContext.
     * This ensures the component has the context required for LMS.
     * It also handles the initial subscription when the context is available.
     */
    @wire(MessageContext)
    wiredContext(context) {
        this.messageContext = context;
        if (context && !this.subscription) {
            this.subscribeToMessageChannel(context);
        }
    }

    /**
     * Subscribes to the Account_Selected__c message channel.
     * @param {import('lightning/messageService').MessageContext} context 
     */
    subscribeToMessageChannel(context) {
        this.subscription = subscribe(
            context,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => {
                // On message, update the selectedAccountId.
                // If recordId is missing or null, clear the selection.
                this.selectedAccountId = message?.recordId ? message.recordId : null;
            },
            { scope: APPLICATION_SCOPE }
        );
    }

    /**
     * Cleans up the subscription when the component is removed from the DOM.
     * This satisfies the requirement to unsubscribe and allow re-subscription.
     */
    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    /**
     * Handles the clear button click by publishing a null recordId.
     * This clears the selection for this component and any other listeners.
     */
    handleClear(event) {
        if (event.target.dataset.action === 'clear') {
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
        }
    }
}
