import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;
    _options = [];
    _value = '';
    activeIndex = 0;

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = value || [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this.syncActiveIndex();
    }

    /**
     * Synchronizes the active index (the visually focused item) with the selected value.
     * If the value doesn't match any option, it defaults to the first option.
     */
    syncActiveIndex() {
        if (this._options && this._options.length > 0) {
            const index = this._options.findIndex(opt => opt.value === this._value);
            this.activeIndex = index !== -1 ? index : 0;
        } else {
            this.activeIndex = 0;
        }
    }

    /**
     * Returns the ID of the currently active option for aria-activedescendant.
     */
    get activeOptionId() {
        return this._options.length > 0 ? `option-${this.activeIndex}` : '';
    }

    /**
     * Maps options to include necessary ARIA attributes and unique IDs.
     */
    get displayedOptions() {
        return this._options.map((opt, index) => ({
            ...opt,
            id: `option-${index}`,
            isSelected: opt.value === this._value
        }));
    }

    /**
     * Handles keyboard navigation for the listbox.
     */
    handleKeyDown(event) {
        if (this._options.length === 0) return;

        const { key } = event;
        let moved = false;

        switch (key) {
            case 'ArrowDown':
                if (this.activeIndex < this._options.length - 1) {
                    this.activeIndex++;
                }
                moved = true;
                break;
            case 'ArrowUp':
                if (this.activeIndex > 0) {
                    this.activeIndex--;
                }
                moved = true;
                break;
            case 'Home':
                this.activeIndex = 0;
                moved = true;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                moved = true;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(this.activeIndex);
                moved = true;
                break;
            default:
                // Allow other keys (like Tab) to behave normally
                return;
        }

        if (moved) {
            event.preventDefault();
        }
    }

    /**
     * Handles selection via mouse click.
     */
    handleOptionClick(event) {
        // Ensure focus stays on the listbox to comply with WAI-ARIA requirements
        const listbox = this.template.querySelector('ul');
        if (listbox) {
            listbox.focus();
        }

        const valueStr = event.currentTarget.dataset.value;
        // Match based on string comparison because dataset attributes are strings
        const index = this._options.findIndex(opt => String(opt.value) === valueStr);

        if (index !== -1) {
            this.activeIndex = index;
            this.selectOption(index);
        }
    }

    /**
     * Dispatches the change event if the selected value is different from the current value.
     */
    selectOption(index) {
        const option = this._options[index];
        if (option && option.value !== this._value) {
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: option.value }
            }));
        }
    }
}
