public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accIds.add(c.AccountId);
            }
        }
        rollup(accIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newC = (Case)triggerNew[i];
            Case oldC = (Case)triggerOld[i];

            if (newC.AccountId != oldC.AccountId) {
                if (oldC.AccountId != null) {
                    accIds.add(oldC.AccountId);
                }
                if (newC.AccountId != null) {
                    accIds.add(newC.AccountId);
                }
            } else if (newC.IsClosed != oldC.IsClosed) {
                if (newC.AccountId != null) {
                    accIds.add(newC.AccountId);
                }
            }
        }
        rollup(accIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accIds = new Set<Id>();
        for (SObject so : triggerOld) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accIds.add(c.AccountId);
            }
        }
        rollup(accIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accIds = new Set<Id>();
        for (SObject so : triggerNew) {
            Case c = (Case)so;
            if (c.AccountId != null) {
                accIds.add(c.AccountId);
            }
        }
        rollup(accIds);
    }

    private void rollup(Set<Id> accIds) {
        if (accIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) total 
            FROM Case 
            WHERE IsClosed = false AND AccountId IN :accIds 
            GROUP BY AccountId
        ]) {
            counts.put((Id)ar.get('AccountId'), (Integer)ar.get('total'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accIds) {
            accountsToUpdate.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = counts.containsKey(accId) ? counts.get(accId) : 0
            ));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
